"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["70792"],{87695(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.fato_candidato.hipotese_legal_obrigatoria","status":422,"titulo":"Hip\xf3tese legal de tratamento do fato \xe9 obrigat\xf3ria"},"descricao":{"codigo":"uniplus.configuracao.fato_candidato.hipotese_legal_obrigatoria","requisitos":["UNI-REQ-0143","UNI-REQ-0205"],"oQueAconteceu":["Todo fato declara a prote\xe7\xe3o de dados: a classifica\xe7\xe3o, a finalidade e a hip\xf3tese legal do tratamento, a base da LGPD que o autoriza (UNI-REQ-0205). A `hipoteseLegal` do cadastro (`POST /api/configuracao/admin/fatos-candidato`, `POST /api/configuracao/admin/fatos-candidato/derivados` ou `POST /api/configuracao/admin/fatos-candidato/agregados`) ou da altera\xe7\xe3o da defini\xe7\xe3o (`PUT /api/configuracao/admin/fatos-candidato/{id}/definicao`), inclusive a do fato de sistema, chegou vazia ou s\xf3 com espa\xe7os. O campo ausente do corpo \xe9 recusado antes, como erro de requisi\xe7\xe3o (400).","A recusa vem na lista `errors` da resposta, com `field` igual a `hipoteseLegal`. Nada \xe9 gravado. Uma hip\xf3tese preenchida que n\xe3o \xe9 do vocabul\xe1rio recebe [a recusa de hip\xf3tese legal fora do vocabul\xe1rio](/erros/uniplus.configuracao.fato_candidato.hipotese_legal_invalida)."],"comoResolver":["Informe a hip\xf3tese legal do tratamento, escrita exatamente como no vocabul\xe1rio, em mai\xfasculas e com sublinhado: a lista completa est\xe1 em [hip\xf3tese legal fora do vocabul\xe1rio](/erros/uniplus.configuracao.fato_candidato.hipotese_legal_invalida). A hip\xf3tese precisa caber na classifica\xe7\xe3o do fato: veja [a hip\xf3tese legal que n\xe3o cabe na classifica\xe7\xe3o](/erros/uniplus.configuracao.fato_candidato.hipotese_legal_incompativel_com_classificacao)."],"ondeAparece":["Cadastro de um fato do cat\xe1logo (declarado, derivado ou resumo de grupo)","Altera\xe7\xe3o da defini\xe7\xe3o de um fato do cat\xe1logo"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Fato candidato"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"0258f07cac6c9b7f9d70290a4b0385549eb99572"}}')}}]);